function ttb_assignments():array{$dir=ttb_pccm_dir();$active=load_json($dir.'/active_version.json',[]);$vid=trim((string)($active['id']??''));if($vid===''){foreach((array)load_json($dir.'/versions.json',[])as$v)if(!empty($v['id'])){$vid=(string)$v['id'];break;}}$rows=$vid!==''?load_json($dir.'/assignments_'.$vid.'.json',[]):load_json($dir.'/assignments.json',[]);$manual=load_json($dir.'/manual_assignments.json',[]);foreach(is_array($manual)?$manual:[]as$r){$rv=trim((string)($r['version_id']??''));if($rv!==''&&$rv!==$vid)continue;$r['class']=$r['class']??$r['class_name']??'';$r['is_manual']=true;$rows[]=$r;}$out=[];foreach(is_array($rows)?$rows:[]as$r){$teacher=trim((string)($r['teacher']??''));$subject=trim((string)($r['subject']??''));$class=trim((string)($r['class']??$r['class_name']??''));$periods=(float)($r['periods']??0);if($teacher===''||$subject===''||$class===''||$periods<=0)continue;$id=trim((string)($r['id']??''))?:hash('sha256',$teacher.'|'.$subject.'|'.$class);$override=(array)(($GLOBALS['CDS_TTB_CURRENT_DATA']['period_overrides']??[])[$id]??[]);if(array_key_exists('periods',$override))$periods=max(0,(float)$override['periods']);if($periods<=0)continue;$out[]=['id'=>$id,'teacher'=>$teacher,'subject'=>$subject,'class'=>$class,'periods'=>$periods,'base_periods'=>(float)($r['periods']??0),'note'=>(string)($r['note']??'')];}usort($out,fn($a,$b)=>strnatcasecmp($a['class'].'|'.$a['subject'],$b['class'].'|'.$b['subject']));return$out;}
