function ttb_compact_cost(array$periods):int{$periods=array_values(array_unique(array_map('intval',$periods)));if(!$periods)return 0;sort($periods);return max(0,max($periods)-count($periods));}
function ttb_candidate_score(array$a,array$s,array$placed,array$settings):int{$score=random_int(0,2);if(!empty($settings['prefer_morning'])&&$s['session']==='Chiều')$score+=5000;$teacher=$a['teacher'];$day=$s['day'];$sameTeacherDay=[];$teacherDays=[];$sameSubjectDay=0;$classDay=0;$sameClassSession=[];foreach($placed as$p){if($p['teacher']===$teacher){$teacherDays[$p['day']]=true;if($p['day']===$day)$sameTeacherDay[]=$p;}if($p['day']===$day&&array_intersect($p['classes'],$a['classes'])){$classDay++;if($p['session']===$s['session'])$sameClassSession[]=(int)$p['period'];if($p['subject']===$a['subject'])$sameSubjectDay++;}}$score+=max(0,$sameSubjectDay+1-(int)($settings['max_subject_class_daily']??2))*180;if(!empty($settings['spread_same_subject']))$score+=$sameSubjectDay*25;$score+=max(0,$classDay+1-(int)($settings['max_class_daily']??10))*500;$classPeriods=$sameClassSession;$classPeriods[]=(int)$s['period'];$score+=ttb_compact_cost($classPeriods)*420;$score+=max(0,count($sameTeacherDay)+1-(int)($settings['max_teacher_daily']??7))*500;if(!isset($teacherDays[$day])&&count($teacherDays)>=(int)($settings['max_teacher_days']??6))$score+=600;if(!empty($settings['optimize_teacher_days'])&&!isset($teacherDays[$day])&&$teacherDays)$score+=10;$teacherPeriods=array_column(array_filter($sameTeacherDay,fn($p)=>$p['session']===$s['session']),'period');$teacherPeriods[]=(int)$s['period'];$score+=ttb_compact_cost($teacherPeriods)*260;if(count($teacherPeriods)>1){sort($teacherPeriods);$run=1;$best=1;for($i=1;$i<count($teacherPeriods);$i++){$run=$teacherPeriods[$i]===$teacherPeriods[$i-1]+1?$run+1:1;$best=max($best,$run);}$score+=max(0,$best-(int)($settings['max_teacher_consecutive']??5))*250;}if(!empty($settings['avoid_edges'])){$maxPeriod=$s['session']==='Sáng'?(int)$settings['morning_periods']:(int)$settings['afternoon_periods'];if($s['period']===$maxPeriod)$score+=8;}return$score;}
function ttb_global_penalty(array$entries,array$settings):int{$byTeacher=[];$byClass=[];foreach($entries as$e){$byTeacher[(string)$e['teacher']][(int)$e['day']][(string)$e['session']][]=(int)$e['period'];foreach((array)$e['classes']as$class)$byClass[(string)$class][(int)$e['day']][(string)$e['session']][]=(int)$e['period'];}$penalty=0;$gapLimit=max(0,(int)($settings['max_teacher_gaps']??2));foreach($byTeacher as$days)foreach($days as$sessions)foreach($sessions as$periods){$compact=ttb_compact_cost($periods);$internal=0;$unique=array_values(array_unique($periods));sort($unique);if(count($unique)>1)$internal=max($unique)-min($unique)+1-count($unique);$penalty+=$compact*420+max(0,$internal-$gapLimit)*600;}foreach($byClass as$days)foreach($days as$sessions)foreach($sessions as$periods)$penalty+=ttb_compact_cost($periods)*700;return$penalty;}
function ttb_validate_entries(array$entries,array$activities):array{$errors=[];$classBusy=[];$teacherBusy=[];$activityMap=[];$pairEntries=[];foreach($activities as$a)$activityMap[$a['id']]=$a;foreach($entries as$e){$key=ttb_slot_key((int)$e['day'],(string)$e['session'],(int)$e['period']);$aid=(string)$e['activity_id'];foreach((array)$e['classes']as$c){$ck=$c.'|'.$key;if(isset($classBusy[$ck])&&$classBusy[$ck]!==$aid)$errors[]='Trùng lớp '.$c.' tại '.$key;$classBusy[$ck]=$aid;}if(!empty($e['pair_id']))$pairEntries[(string)$e['pair_id']][]=$e;$tk=$e['teacher'].'|'.$key;if(isset($teacherBusy[$tk])&&$teacherBusy[$tk]!==$aid)$errors[]='Trùng giáo viên '.$e['teacher'].' tại '.$key;$teacherBusy[$tk]=$aid;}foreach($pairEntries as$pairId=>$pair){if(count($pair)!==2){$errors[]='Cặp tiết liền nhau chưa đủ: '.$pairId;continue;}$a=$pair[0];$b=$pair[1];if($a['day']!==$b['day']||$a['session']!==$b['session']||abs((int)$a['period']-(int)$b['period'])!==1)$errors[]='Hai tiết bắt buộc liền nhau đã bị tách: '.$a['subject'].' '.implode('+',(array)$a['classes']);}return array_values(array_unique($errors));}
function ttb_plan_diagnostics(array$data,array$assignments,array$plan):array{$activities=ttb_activities($assignments,(array)$data['groups']);$entries=(array)($plan['entries']??[]);$unplaced=(array)($plan['unplaced']??[]);$slots=ttb_slots($data['settings']);$classes=array_values(array_unique(array_column($assignments,'class')));$placedByClass=array_fill_keys($classes,0);$placedIds=[];$teacherBusy=[];$classBusy=[];foreach($entries as$e){$placedIds[(string)$e['activity_id']]=true;$key=ttb_slot_key((int)$e['day'],(string)$e['session'],(int)$e['period']);$teacherBusy[(string)$e['teacher'].'|'.$key]=true;foreach((array)$e['classes']as$c){$placedByClass[$c]=(int)($placedByClass[$c]??0)+1;$classBusy[$c.'|'.$key]=true;}}$missingByClass=[];$missingBySubject=[];$missingByTeacher=[];$bottlenecks=[];foreach($unplaced as$a){foreach((array)$a['classes']as$c)$missingByClass[$c]=(int)($missingByClass[$c]??0)+1;$missingBySubject[$a['subject']]=(int)($missingBySubject[$a['subject']]??0)+1;$missingByTeacher[$a['teacher']]=(int)($missingByTeacher[$a['teacher']]??0)+1;$base=0;$teacherFree=0;$classFree=0;foreach($slots as$s){if(!empty($a['fixed_day'])&&($s['day']!==$a['fixed_day']||(!empty($a['fixed_session'])&&$s['session']!==$a['fixed_session'])||(!empty($a['fixed_period'])&&$s['period']!==$a['fixed_period'])))continue;if(ttb_slot_unavailable($data,$a,$s))continue;$base++;if(empty($teacherBusy[$a['teacher'].'|'.$s['key']]))$teacherFree++;$ok=true;foreach((array)$a['classes']as$c)if(!empty($classBusy[$c.'|'.$s['key']])){$ok=false;break;}if($ok)$classFree++;}$reason=$base===0?'Bị khóa toàn bộ khung giờ':($teacherFree===0?'Giáo viên kín lịch':($classFree===0?'Lớp kín lịch':'Xung đột đồng thời giáo viên và lớp'));$bottlenecks[$reason]=(int)($bottlenecks[$reason]??0)+1;}$free=0;foreach($classes as$c)$free+=max(0,count($slots)-(int)($placedByClass[$c]??0));return['total'=>count($activities),'placed'=>count($entries),'unplaced'=>count($unplaced),'slot_capacity'=>count($slots)*count($classes),'free_class_slots'=>$free,'empty_classes'=>array_keys(array_filter($placedByClass,fn($n)=>$n===0)),'missing_class'=>$missingByClass,'missing_subject'=>$missingBySubject,'missing_teacher'=>$missingByTeacher,'bottlenecks'=>$bottlenecks];}
function ttb_generate(array$data,array$assignments,array$locked=[]):array{$settings=$data['settings'];$activities=ttb_apply_lesson_rules(ttb_activities($assignments,(array)$data['groups']),$data);$slots=ttb_slots($settings);$best=null;$deadline=microtime(true)+max(3,min(30,(int)($settings['run_seconds']??8)));$attempts=max(1,min(100,(int)($settings['attempts']??40)));
 for($attempt=0;$attempt<$attempts&&microtime(true)<$deadline;$attempt++){$placed=[];$classBusy=[];$teacherBusy=[];$lockedIds=[];foreach($locked as$e)if(!empty($e['locked'])&&!ttb_slot_unavailable($data,$e,['key'=>ttb_slot_key((int)$e['day'],(string)$e['session'],(int)$e['period'])])){$placed[]=$e;$lockedIds[$e['activity_id']]=true;$key=ttb_slot_key($e['day'],$e['session'],$e['period']);foreach($e['classes']as$c)$classBusy[$c.'|'.$key]=true;$teacherBusy[$e['teacher'].'|'.$key]=true;}$todo=array_values(array_filter($activities,fn($a)=>empty($lockedIds[$a['id']])));shuffle($todo);usort($todo,function($a,$b){if(!empty($a['pair_id'])&&$a['pair_id']===($b['pair_id']??''))return($a['pair_order']??1)<=>($b['pair_order']??1);$fa=($a['fixed_day']?10000:0)+(!empty($a['pair_id'])?20000:0)+count($a['classes'])*100;$fb=($b['fixed_day']?10000:0)+(!empty($b['pair_id'])?20000:0)+count($b['classes'])*100;if($fa!==$fb)return$fb<=>$fa;if(!empty($a['pair_id'])&&!empty($b['pair_id']))return$a['pair_id']<=>$b['pair_id'];return 0;});$unplaced=[];$score=0;
  foreach($todo as$a){$candidates=[];foreach($slots as$s){if(!empty($a['allowed_session'])&&$s['session']!==$a['allowed_session'])continue;if(!empty($a['allowed_period_from'])&&$s['period']<(int)$a['allowed_period_from'])continue;if(!empty($a['allowed_period_to'])&&$s['period']>(int)$a['allowed_period_to'])continue;if($a['fixed_day']&&($s['day']!==$a['fixed_day']||($a['fixed_session']!==''&&$s['session']!==$a['fixed_session'])||($a['fixed_period']&&$s['period']!==$a['fixed_period'])))continue;if(ttb_slot_unavailable($data,$a,$s))continue;if(!empty($a['pair_id'])){$partner=null;foreach($placed as$p)if(($p['pair_id']??'')===$a['pair_id']){$partner=$p;break;}if($partner){if($s['day']!==$partner['day']||$s['session']!==$partner['session']||abs($s['period']-$partner['period'])!==1)continue;}else{$maxPair=$s['session']==='Sáng'?(int)$settings['morning_periods']:(int)$settings['afternoon_periods'];$pairSpace=false;foreach([$s['period']-1,$s['period']+1]as$near){if($near<1||$near>$maxPair)continue;$nearKey=ttb_slot_key($s['day'],$s['session'],$near);if(ttb_slot_unavailable($data,$a,['key'=>$nearKey])||isset($teacherBusy[$a['teacher'].'|'.$nearKey]))continue;$pairBad=false;foreach($a['classes']as$c)if(isset($classBusy[$c.'|'.$nearKey])){$pairBad=true;break;}if(!$pairBad){$pairSpace=true;break;}}if(!$pairSpace)continue;}}if(isset($teacherBusy[$a['teacher'].'|'.$s['key']]))continue;$bad=false;foreach($a['classes']as$c)if(isset($classBusy[$c.'|'.$s['key']])){$bad=true;break;}if($bad)continue;$candidates[]=['slot'=>$s,'score'=>ttb_candidate_score($a,$s,$placed,$settings)];}if(!$candidates){$unplaced[]=$a;continue;}usort($candidates,fn($x,$y)=>$x['score']<=>$y['score']);$pick=$candidates[0];$s=$pick['slot'];$entry=array_merge($a,['activity_id'=>$a['id'],'day'=>$s['day'],'session'=>$s['session'],'period'=>$s['period'],'locked'=>false]);$placed[]=$entry;$score+=$pick['score'];$teacherBusy[$a['teacher'].'|'.$s['key']]=true;foreach($a['classes']as$c)$classBusy[$c.'|'.$s['key']]=true;}
  $score+=ttb_global_penalty($placed,$settings)+count($unplaced)*100000;$candidate=['entries'=>$placed,'unplaced'=>$unplaced,'score'=>$score,'errors'=>ttb_validate_entries($placed,$activities)];if($best===null||$candidate['score']<$best['score'])$best=$candidate;if(!$unplaced&&$score<20)break;}
 $best=$best??['entries'=>[],'unplaced'=>$activities,'score'=>PHP_INT_MAX,'errors'=>[]];$best['id']='plan_'.date('YmdHis').'_'.bin2hex(random_bytes(2));$best['name']='Phương án '.date('d/m/Y H:i');$best['created_at']=date('c');return$best;}
function ttb_plan(array$data,string$id):?array{foreach((array)$data['plans']as$p)if(($p['id']??'')===$id)return$p;return null;}
function ttb_replace_plan(array&$data,array$plan):void{$found=false;foreach($data['plans']as&$p)if(($p['id']??'')===($plan['id']??'')){$p=$plan;$found=true;break;}unset($p);if(!$found)$data['plans'][]=$plan;$data['active_plan']=$plan['id'];$data['plans']=array_slice($data['plans'],-12);}
function ttb_publish(array$plan,string$name,string$from,string$to,array$user,bool$overwrite=false,string$weekKey=''):array{if(!empty($plan['unplaced'])||!empty($plan['errors']))return['ok'=>false,'message'=>'Phương án còn tiết chưa xếp hoặc xung đột.'];$slots=[];$teacherMap=[];$classMap=[];foreach($plan['entries']as$e)foreach($e['classes']as$class){$teacher=(string)$e['teacher'];$slots[]=['day'=>(int)$e['day'],'session'=>(string)$e['session'],'period'=>(int)$e['period'],'class_raw'=>$class,'subject'=>(string)$e['subject'],'teacher_raw'=>$teacher,'group_session_id'=>(string)($e['group_id']??''),'teacher_credit'=>($e['credit_mode']??'per_class')==='per_class'?1:1/max(1,count($e['classes']))];$teacherMap[$teacher]=$teacher;$classMap[$class]=$class;}$weeks=tkb_weeks();$existing=[];foreach($weeks as$i=>$w)if((($w['start_date']??'')===$from&&($w['end_date']??'')===$to)||($weekKey!==''&&($w['school_week_key']??'')===$weekKey))$existing[]=$i;if($existing&&!$overwrite)return['ok'=>false,'message'=>'Tuần đã có thời khóa biểu. Hãy xác nhận ghi đè để tiếp tục.','needs_overwrite'=>true];foreach($weeks as&$w)$w['active']=false;unset($w);if($existing&&$overwrite)foreach($existing as$i){$weeks[$i]['replaced_at']=date('c');$weeks[$i]['replaced_by_plan']=(string)$plan['id'];}$week=['id'=>'tkb_'.date('YmdHis').'_'.bin2hex(random_bytes(2)),'label'=>$name,'school_week_key'=>$weekKey,'start_date'=>$from,'end_date'=>$to,'active'=>true,'uploaded_at'=>date('c'),'uploaded_by'=>$user['name']??'','source'=>'builder','builder_plan_id'=>$plan['id'],'slots'=>$slots];$weeks[]=$week;if(!tkb_save(TKB_WEEKS_FILE,$weeks))return['ok'=>false,'message'=>'Không lưu được tuần TKB mới.'];tkb_save_mapping($teacherMap,$classMap);return['ok'=>true,'version'=>$week,'message'=>'Đã công bố '.$name.' vào tuần đã chọn.'.($existing?' Bản cũ được giữ trong lịch sử.':'')];}
